//! The persisted format: the version number, the reader's caps, and the
//! read-any-version / write-current pair behind `project.json` in a
//! `.framejob` package (spec §5.6).
//!
//! The rule this module exists to enforce: **the reader accepts every prior
//! version, and the writer enforces the reader's caps**, so every file this
//! build produces can be read back by this build. Any change to the
//! persisted schema bumps [`RC_FORMAT_VERSION`] here AND the `#define` in
//! `core/include/framejob_core.h`, and adds a migration step in [`read`].

use serde_json::{json, Value};

use crate::model::{Canvas, Project};

/// Bumped by any change to the persisted project schema. Mirrored by
/// `RC_FORMAT_VERSION` in the C header.
/// What each version added is [`crate::format_history`].
pub const RC_FORMAT_VERSION: u32 = 43;

/// The number the grading branch's builds wrote (spec §11 GR-9); read as version 15.
pub const GRADING_BRANCH_VERSION: u32 = 1015;

/// Reader caps, mirrored by the `RC_MAX_*` defines in the C header. They
/// exist so a corrupt or generated file cannot make the app allocate
/// without bound, and they are generous: 4096 clips is far past what the
/// timeline UI stays usable at.
pub const MAX_CLIPS: usize = 4096;
pub const MAX_TRACKS: usize = 64;
pub const MAX_MARKERS: usize = 1024;
pub const MAX_MEDIA: usize = 1024;

/// The largest `.cube` file `cube.rs` reads (spec §11 GR-8): 32 MiB, which
/// holds a 65³ table four times over at the precision tools write, and keeps
/// a stray file named `.cube` from being read whole. Mirrored by
/// `RC_CUBE_MAX_BYTES` in the C header; the app reads at most one byte more,
/// so a larger file is refused by the core's own sentence.
pub const RC_CUBE_MAX_BYTES: usize = 33_554_432;

/// How many levels of nest may sit inside one another. A cap on the WALK,
/// not on taste: every evaluation of a nested layer recurses once per
/// level, and eight levels is already past anything an editor does on
/// purpose. `Project::validate` refuses a deeper file, and it refuses a
/// nest that reaches itself at any depth, so no walk downstream needs a
/// visited set of its own.
pub const MAX_NEST_DEPTH: u32 = 8;

/// The caps check both sides share: [`Project::validate`] runs it on read,
/// [`write`] runs it before serializing. One implementation, so the writer
/// can never produce a file the reader rejects.
///
/// Nested tracks and clips count toward the same two caps as the
/// timeline's. They are the same tracks and clips — a nest is a group held
/// in the parent's one id space, and flattening one at evaluation time
/// gives its clips real composition tracks — so counting them separately
/// would let a project with 64 nests of 64 tracks past a cap that exists to
/// bound exactly that.
pub fn check_caps(p: &Project) -> Result<(), String> {
    let nested_clips: usize = p.nests.iter().map(|n| n.clips.len()).sum();
    let nested_tracks: usize = p.nests.iter().map(|n| n.tracks.len()).sum();
    let clips = p.clips.len().saturating_add(nested_clips);
    let tracks = p.tracks.len().saturating_add(nested_tracks);
    if clips > MAX_CLIPS {
        return Err(format!("too many clips: {clips} (max {MAX_CLIPS})"));
    }
    if tracks > MAX_TRACKS {
        return Err(format!("too many tracks: {tracks} (max {MAX_TRACKS})"));
    }
    if p.markers.len() > MAX_MARKERS {
        return Err(format!(
            "too many markers: {} (max {})",
            p.markers.len(),
            MAX_MARKERS
        ));
    }
    if p.media.len() > MAX_MEDIA {
        return Err(format!(
            "too many media: {} (max {})",
            p.media.len(),
            MAX_MEDIA
        ));
    }
    Ok(())
}

/// Version 1 → 2. One key needs rewriting: a nest clip's `project`.
///
/// In version 1 it was a PATH — a reference the core, which has no
/// filesystem, could never resolve, so `evaluate.rs` could only drop the
/// clip — and in version 2 it is the id of a `Nest` in `nests[]`. No build
/// ever created one (no op makes a nest yet; the reader round-tripped the
/// key and nothing else), so nothing real is being reinterpreted here. The
/// step exists because "the reader accepts every prior version" is a
/// promise about hand-written and third-party files too, and a `String`
/// where a `u32` now belongs is the one version-1 shape serde cannot take
/// with a default.
///
/// The path becomes an EMPTY nest carrying it as a name. That keeps the
/// clip — its track, its times, its transform, its actions — and loses only
/// a reference that never resolved to anything; deleting the clip instead
/// would silently throw away something a person placed on a timeline.
///
/// Anything else is left exactly as it is. A shape this cannot make sense
/// of gets serde's schema error, naming the key, rather than a guess made
/// here.
fn migrate_1_to_2(value: &mut Value) {
    let default_canvas = Canvas::default();
    let width = value
        .pointer("/canvas/width")
        .and_then(Value::as_u64)
        .unwrap_or(u64::from(default_canvas.width));
    let height = value
        .pointer("/canvas/height")
        .and_then(Value::as_u64)
        .unwrap_or(u64::from(default_canvas.height));
    // Ids come from the file's own counter, which is exactly what it is
    // for: `validate` demands `next_id` be past every id in the project, so
    // allocating from it cannot collide with one.
    let mut next_id = value.get("next_id").and_then(Value::as_u64).unwrap_or(1);

    let mut made: Vec<Value> = Vec::new();
//! The op envelope — the ONE edit entry point (spec §6, spec §7.1).
//!
//! Every edit the app or the agent makes arrives here as one JSON object,
//! `{"op": "<name>", ...arguments}`, and leaves as a new project. This
//! module owns the envelope and nothing else: [`Op`] is the schema, and
//! [`Project::apply`] is a flat dispatch table with no logic in it. The
//! semantics live in `edit_clip.rs`, `edit_props.rs`, `edit_track.rs` and
//! `edit_time.rs`.
//!
//! **The table below IS what an op MEANS**, and [`crate::op_table`] is
//! what one TAKES: its rows are the argument names, kinds and required-ness
//! that used to be a markdown column here, as data a caller can read.
//! `app/Sources/ReelOps.swift`'s typed builders mirror the two together, and
//! `AgentCatalog*.swift`'s tools PRINT the arguments half (`rc_op_schemas`).
//!
//! Reading the table:
//!
//! - **Times are ticks**: `i64` at 600 000 per second ([`crate::TIMESCALE`]),
//!   the timescale that divides every common frame duration exactly.
//! - **Caller-supplied timeline time arguments are snapped to the canvas frame
//!   grid** (usually round to nearest; `add_transition` floors its requested
//!   overlap), durations included, so a caller may pass a value
//!   computed from a pixel position without rounding it itself. A negative
//!   PROJECT time is clamped to 0 — a drag can start left of the timeline
//!   and there is no negative time there — while a negative LENGTH is an
//!   `Err`, and so is a negative CLIP time (`add_action`, `set_action`):
//!   the caller computes those as `playhead − clip.start`, so a negative
//!   one means the playhead is not on the clip, which is a caller bug and
//!   not a gesture to round off.
//! - **A shift moves every clip it moves by ONE delta** (spec §11 #42):
//!   the ripples, `close_gap`, `insert_time` and `move_clip` keep relative
//!   placement exact, so at a rate whose frame is not a whole number of
//!   ticks (7 fps) a moved start may sit a tick off the grid.
//! - **A linked pair moves as one in time** (spec §11 AU-90…AU-96):
//!   `clips[].linked` names a clip's partner, mutually and in one container.
//!   Every placement op takes the partner on an unlocked track with the clip
//!   it was given (its row says how), and `finish` clears any link left
//!   one-sided, so an op that removes or replaces half a pair needs no rule
//!   of its own. A linked clip's speed and direction are refused.
//! - **What an absent optional argument MEANS is said here**, in the
//!   Semantics column, and which arguments are optional at all is
//!   [`crate::op_table`]. An optional argument may be omitted. Most are
//!   `Option<T>` and decode an explicit `null` like absence; the eight
//!   defaulted plain booleans reject null and default to false when omitted.
//! - **A new id is the project's `next_id` from BEFORE the call.** An op
//!   returns a project, not a value, so a caller that needs the id of the
//!   clip, track, marker or media it just added reads `next_id` first. An
//!   op minting MORE than one gives them ids in the order it CREATES them —
//!   the rule is that order and never a closed list of such ops, which was
//!   wrong on the third of them: `add_background` and
//!   `add_blurred_background` create the TRACK and then the clip on it;
//!   `detach_audio` on a bottom-track clip does the same and then re-mints
//!   an id per action it carried; `nest` mints the nest, a track per track
//!   it swallows, then the nest clip.
//! - Unknown keys are an error, in the envelope and in every property
//!   patch: a typo in a hand-written op or an agent call is a mistake to
//!   report, not a silent no-op. In a property patch a value of the wrong
//!   kind and a misspelt variant are errors too — never read as a clear,
//!   and a list or an object is never read field by field as something
//!   else — and the refusal names the dotted path to the mistake, array
//!   indices included, and the value sent: `unknown key "filters[1].kindd"
//!   in a video patch`, `bad value at "shadow" in a video patch: expected
//!   an object, not 5`. An action's `end` patch is walked the same way —
//!   the three groups it may name are `video`, `audio` and `text` (and a
//!   graphic's props through a door of its own, G-34), and its
//!   paths carry the group (`unknown key "video.filters[1].kindd" in an
//!   action end patch`) — but its VALUES are not range-checked (a graphic
//!   prop's excepted, G-34 (c)), because an end state may name what no
//!   stored group could hold.
//!   `set_clip` is the fifth patch op. In every patch an absent key keeps
