//! Insert and overwrite — spec §6 rows `insert_clip` and `overwrite_clip`.
//!
//! The two ways to bring new material into a cut that is already timed.
//! An **insert** makes room for it: the track is cut under the drop point
//! and everything from there on moves later by the new clip's length, so
//! nothing is lost and every following clip keeps its relative timing. An
//! **overwrite** takes room from what is there: the span the new clip needs
//! is cleared on that track alone and nothing moves at all, so the cut's
//! total length and every other track are untouched — but for a cut clip's
//! linked partner, which `split_clips` cuts at the same bound (spec §11
//! AU-92).
//!
//! Both are compositions of ops that already exist — `split_clips`,
//! `insert_time`, `add_clip` — and both are ONE op anyway, for two reasons.
//! The first is undo: a drop from the media list is one gesture and must be
//! one step, and three ops applied in a row are three. The second is that
//! the composition has a rule in it that neither half states — an insert
//! cuts only the DESTINATION track and then shifts every unlocked one, so
//! the straddling clips elsewhere ride the shift whole (spec §11's rule 3)
//! while the one under the drop is cut. Written out at each call site, that
//! rule would be restated in the timeline, the menu and the MCP handler.
//!
//! Neither op invents a length: `whole_media_length` is what `add_clip`
//! itself uses, so the room an insert opens is exactly the room the clip
//! needs.

use crate::edit_clip::clip_end;
use crate::edit_time::locked_track;
use crate::model::Project;
use crate::outcome::Outcome;
use crate::time::Ticks;

impl Project {
    /// The insert edit: `media` lands whole at `at` on `track`, and
    /// everything at or after `at` moves later by its length (spec §6).
    ///
    /// The clip `at` falls strictly inside on THIS track is split first, so
    /// the insert lands between two clips rather than on top of one. Other
    /// tracks are not cut: `insert_time` shifts them whole, straddlers
    /// staying put, which is what keeps a music bed unbroken under an
    /// insert into the picture. The one exception is a cut clip's linked
    /// partner on an unlocked track, which `split_clips` cuts at the same
    /// `at` and pairs with it (spec §11 AU-92), so the pair stays in step
    /// through the inserted time.
    ///
    /// **A locked destination track refuses**, up front rather than by
    /// collision. `insert_time` will not shift a locked track, so the room
    /// an insert promises cannot be made there at all; leaving it to
    /// `add_clip` to notice would refuse only where the locked track
    /// happened to hold something at `at`, and quietly add a clip to a
    /// locked track everywhere else. `close_gap` refuses for the same
    /// reason.
    ///
    /// `Err` for an unknown track or media, or a media with no duration; a
    /// locked destination track refuses in [`locked_track`]'s words, and so
    /// does anything the inner `split`, `insert_time` or `add_clip` refused
    /// — this op answers in the words of whichever step declined.
    pub fn insert_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
        if self.require_track(track)?.locked {
            return Ok(Outcome::Refused(locked_track(
                track,
                "an insert cannot open room on it",
            )));
        }
        let found = self.require_media(media)?.clone();
        let at = self.snapped(at).max(0);
        let length = self.whole_media_length(&found)?;

        let straddling: Vec<u32> = self
            .clips_on_track(track)
            .iter()
            .filter(|c| c.start < at && at < clip_end(c))
            .map(|c| c.id)
            .collect();
        let mut next = match self.split_clips(&straddling, at)? {
            Outcome::Applied(split) => split,
            // Nothing straddled the insertion point, which is the ordinary
            // case: carry on with the project as it is.
            Outcome::Identity => self.clone(),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        match next.insert_time(at, length)? {
            Outcome::Applied(opened) => next = opened,
            Outcome::Identity => {}
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        }
        // A composition answers in the words of whichever step declined, so
        // the overlap rule's sentence reaches the caller through here too.
        let placed = match next.add_clip(track, media, at)? {
            Outcome::Applied(placed) => placed,
            Outcome::Identity => return Ok(Outcome::Identity),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        self.finish(placed)
    }

    /// The overwrite edit: `media` lands whole at `at` on `track`, and
    /// whatever that track was playing across the span it needs is removed
    /// (spec §6). Nothing moves, and no other track is touched but for a
    /// cut clip's linked partner on an unlocked track: `split_clips` cuts it
    /// at the same bounds and pairs the pieces (spec §11 AU-92), and the
    /// partner's middle piece stays, its link settled away with the
    /// picture it was paired to.
    ///
    /// The span is cut at both bounds first, so everything that touched it
    /// afterwards lies entirely inside it and can be dropped whole; a clip
    /// that covered the whole span becomes a head and a tail with the new
    /// clip between them.
    ///
    /// The named track is cleared whether or not it is LOCKED — the caller
    /// named it, exactly as `ripple_delete` removes the clips it was given
    /// — while a lock still decides what may shift, which here is nothing.
    ///
    /// `Err` for an unknown track or media, or a media with no duration;
    /// whatever `add_clip` answered when the clip could not be placed after
    /// the span was cleared, in its own words.
    pub fn overwrite_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
        self.require_track(track)?;
        let found = self.require_media(media)?.clone();
        let at = self.snapped(at).max(0);
        let length = self.whole_media_length(&found)?;
        // Both bounds are already on the frame grid, so the span is too.
        let end = at.saturating_add(length);

        let mut next = self.clone();
        for bound in [at, end] {
            let cut: Vec<u32> = next
                .clips_on_track(track)
                .iter()
                .filter(|c| c.start < bound && bound < clip_end(c))
                .map(|c| c.id)
                .collect();
            match next.split_clips(&cut, bound)? {
                Outcome::Applied(project) => next = project,
                Outcome::Identity => {}
                Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
            }
        }
        let inside: Vec<u32> = next
            .clips_on_track(track)
            .iter()
            .filter(|c| c.start >= at && clip_end(c) <= end)
            .map(|c| c.id)
            .collect();
        next.clips.retain(|c| !inside.contains(&c.id));

        let placed = match next.add_clip(track, media, at)? {
            Outcome::Applied(placed) => placed,
            Outcome::Identity => return Ok(Outcome::Identity),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        self.finish(placed)
    }
}

}

// ---- adding clips ----------------------------------------------------

/// Places the whole of `media` as one clip at `at` on `track`, source
/// in 0, with Fit scale when the canvas asks for it and the source
/// exceeds it (spec §6).
///
/// `video` is `null` for an audio-only file and `audio` is `null` for a
/// file with no audio track, which is how the inspector knows which
/// tabs to enable. Refuses when the placement breaks the overlap rule;
/// `Err` for an unknown track or media, or a media with no usable
/// duration.
pub fn add_clip(&self, track: u32, media: u32, at: Ticks) -> Result<Outcome, String> {
    self.require_track(track)?;
    let found = self.require_media(media)?.clone();
    // A drag can start left of zero; the timeline has no negative time.
    let at = self.snapped(at).max(0);

    let duration = self.whole_media_length(&found)?;
    let source = match found.kind {
        MediaKind::Image => Source::Image { media },
        MediaKind::Video | MediaKind::Audio => Source::Media {
            media,
            r#in: 0,
            reversed: false,
        },
        MediaKind::Lut => return Err(crate::lut::lut_not_placeable(media)),
    };

    let has_pixels = found.has_video || matches!(found.kind, MediaKind::Image);
    let video = has_pixels.then(|| VideoProps {
        scale: self.fit_scale(f64::from(found.width), f64::from(found.height)),
        ..VideoProps::default()
    });
    let audio = found.has_audio.then(AudioProps::default);

    let mut next = self.clone();
    let clip = Clip {
        video,
        audio,
        ..Clip::placed(next.allocate_id(), track, at, duration, source)
    };
    self.commit_additions(next, vec![clip])
}

// ---- moving -----------------------------------------------------------

/// Shifts `clips` by `delta` ticks and, when `track` is given, moves
/// them to that track keeping their relative track offsets (spec §6).
///
/// The EARLIEST clip clamps at 0 and the rest keep their offsets, so a
/// drag past the start of the timeline compresses nothing. The
/// destination is computed as an index delta from the first clip of the
/// selection (by track order, then start), which is what makes a
/// two-track selection land two tracks apart.
///
/// Refuses when a clip would land outside the track list or the overlap
/// rule fails on any affected track. A clip that gains a predecessor
/// overlap and has no transition gets a cross dissolve.
///
/// **A linked partner follows in TIME, not in track** (spec §11 AU-91):
/// every clip of the closure moves by the one delta, the clamp at 0 is
/// taken over the closure so a J-cut's lead is kept, and the track delta
/// is anchored on and applied to the CALLER's clips only — so a sound
/// half dragged to a track of its own goes alone and its picture stays.
pub fn move_clips(
    &self,
    clips: &[u32],
    delta: Ticks,
    track: Option<u32>,
) -> Result<Outcome, String> {
    let selection = self.selected_clips(clips)?;
    if selection.is_empty() {
        return Ok(Outcome::Identity);
    }
    let closure = self.selected_clips(&self.with_links(clips)?)?;

    // Snapping the delta keeps a dragged clip on the grid: every start
    // is already on it, so a snapped delta lands on it too.
    let mut delta = self.snapped(delta);
    let earliest = closure.iter().map(|c| c.start).min().unwrap_or(0);
    if delta < -earliest {
        delta = -earliest;
    }

    let index_delta = match track {
        None => 0i64,
        Some(destination) => {
            let destination_index = self.require_track_index(destination)? as i64;
            // The anchor is the FIRST clip of the selection in the
            // order the timeline draws — back-most track, then earliest
            // — and the whole selection moves by its offset, which is
            // what keeps a two-track selection two tracks apart.
            let mut keyed: Vec<(usize, Ticks, u32)> = Vec::new();
            for clip in &selection {
                keyed.push((self.require_track_index(clip.track)?, clip.start, clip.id));
            }
            let anchor = keyed.iter().min().map(|k| k.0).unwrap_or(0) as i64;
            destination_index - anchor
        }
    };

    let mut candidates: Vec<Clip> = Vec::new();
    for clip in &closure {
        let mut moved = (*clip).clone();
        moved.start = moved.start.saturating_add(delta).max(0);
        let named = selection.iter().any(|c| c.id == clip.id);
        if index_delta != 0 && named {
            let from = self.require_track_index(clip.track)? as i64;
            let to = from.saturating_add(index_delta);
            // A selection dragged off either end of the track list is a
            // refusal and not a clamp — clamping would silently stack
            // two clips on one track — and it says so in `move_track`'s
            // own words for the same mistake.
            let Some(destination) = usize::try_from(to)
                .ok()
                .and_then(|index| self.tracks.get(index))
            else {
                return Ok(Outcome::Refused(format!(
                    "clip {} would land on track index {to}, which is out of range (0..{})",
                    clip.id,
                    self.tracks.len()
                )));
            };
            moved.track = destination.id;
        }
        candidates.push(moved);
    }

    self.commit_replacements(candidates)
}

/// The named clips, deduplicated, in the order given. `Err` on an
/// unknown id — every multi-clip op names its clips explicitly, so a
/// stale id is a caller bug, not a refusal.
pub(crate) fn selected_clips(&self, clips: &[u32]) -> Result<Vec<&Clip>, String> {
    let mut out: Vec<&Clip> = Vec::new();
    for id in clips {
        let clip = self.require_clip(*id)?;
        if !out.iter().any(|c| c.id == clip.id) {
            out.push(clip);
        }
    }
    Ok(out)
}

