//! Ripple, insert time, range delete, lift, close gap and freeze frame —
//! spec §6 rows `ripple_delete`, `ripple_delete_range`,
//! `ripple_delete_ranges`, `lift_range`, `close_gap`, `insert_time` and
//! `freeze_frame`, and the §11 decisions they implement.
//!
//! What separates these from `edit_clip.rs`'s ops is that they move
//! material they were never given: closing or opening a hole in the cut
//! shifts clips the caller did not name, on tracks the caller did not name.
//! Three rules run through all of it (spec §11):
//!
//! 1. **Ripple is timeline-wide.** A ripple shifts every UNLOCKED track,
//!    not only the tracks the removed clips were on — that is the one
//!    behaviour that keeps a music bed in sync with the
//!    picture it was cut to.
//! 2. **Locked tracks never move.** Locking a track is how the user says
//!    "this stays where it is", and it is the only protection from a
//!    timeline-wide shift.
//! 3. **Straddling clips stay put.** A clip that covers a boundary is not
//!    cut by a shift; only clips that begin at or after the boundary move.
//!    Clips never push each other, and a shift never splits anything the
//!    user did not ask to split.
//!
//! Everything here is composed from the primitives in `edit_clip.rs` —
//! `split_clips`, `split_under_playhead`, `snapped`, `finish` — rather than
//! restating them, so a split made by a range delete is the same split ⌘T
//! makes.

use crate::cursor_props::with_base_cursor;
use crate::edit_clip::clip_end;
use crate::model::{Clip, Enabled, Project, Source, VideoProps};
use crate::outcome::Outcome;
use crate::source_window::source_read_by;
use crate::time::{Ticks, TIMESCALE};

/// Default freeze length (spec §6). Two seconds is long enough for a hold
/// to read as deliberate and short enough that the user trims it rather
/// than deletes it.
const DEFAULT_FREEZE_DURATION: Ticks = 2 * TIMESCALE;

/// A half-open span of project time a ripple removes.
#[derive(Debug, Clone, Copy)]
struct Span {
    start: Ticks,
    end: Ticks,
}

/// The spans merged into disjoint ones, ascending.
///
/// Adjacent spans merge as well as overlapping ones: two clips that meet at
/// a cut leave ONE hole, and shifting twice by two lengths is the same as
/// shifting once by their sum only when the boundaries are handled in one
/// piece. Empty spans are dropped — a zero-length hole moves nothing.
fn union(mut spans: Vec<Span>) -> Vec<Span> {
    spans.sort_by_key(|s| (s.start, s.end));
    let mut out: Vec<Span> = Vec::new();
    for span in spans {
        if span.end <= span.start {
            continue;
        }
        match out.last_mut() {
            Some(last) if span.start <= last.end => last.end = last.end.max(span.end),
            _ => out.push(span),
        }
    }
    out
}

/// THE locked-track refusal, written once (spec §5.5, deepening D2·3).
///
/// Three ops refuse over a lock — `close_gap` and `insert_clip` on their
/// destination track, `add_transition`'s ripple form on the incoming clip's
/// track — and each has its own consequence to report, so `what` is the
/// clause after the comma. What every caller acts on is the same: the id of
/// the track to unlock.
pub(crate) fn locked_track(track: u32, what: &str) -> String {
    format!("track {track} is locked, so {what}")
}

/// The ids of every track a timeline-wide shift may touch.
pub(crate) fn unlocked_tracks(project: &Project) -> Vec<u32> {
    project
        .tracks
        .iter()
        .filter(|t| !t.locked)
        .map(|t| t.id)
        .collect()
}

/// What a shift at `from` moves: every clip on an unlocked track starting
/// at or after `from` (rule 3: a straddler stays), and each one's linked
/// partner on an unlocked track, whatever its start (spec §11 AU-91).
pub(crate) fn shifted(project: &Project, from: Ticks) -> Vec<u32> {
    let unlocked = unlocked_tracks(project);
    let mut out: Vec<u32> = Vec::new();
    for clip in project.clips.iter().filter(|c| c.start >= from) {
        let partner = project.partner(clip.id).map(|p| (p.id, p.track));
        for (id, track) in [Some((clip.id, clip.track)), partner].into_iter().flatten() {
            if unlocked.contains(&clip.track) && unlocked.contains(&track) && !out.contains(&id) {
                out.push(id);
            }
        }
    }
    out
}

/// THE shift primitive: exactly [`shifted`]'s clips move by `delta`, in
/// place. Ripple, the range form and insert time differ only in what they
/// compute for `from` and `delta`. `Some` refusal, nothing moved, when a
/// partner leading its clip would start before 0; the caller answers it as
/// [`Outcome::Refused`] (a ripple closes fully or not at all).
pub(crate) fn shift_clips(project: &mut Project, from: Ticks, delta: Ticks) -> Option<String> {
    if delta == 0 {
        return None;
    }
    let moving = shifted(project, from);
    for id in &moving {
        let Some(clip) = project.clip(*id) else {
            continue;
        };
        if clip.start.saturating_add(delta) < 0 {
            if let Some(partner) = project.partner(*id) {
                return Some(format!(
                    "clip {id} would start before 0: it leads its linked clip {} by {} ticks",
                    partner.id,
                    partner.start.saturating_sub(clip.start)
                ));
            }
        }
    }
    for clip in project.clips.iter_mut() {
        if moving.contains(&clip.id) {
            // Saturating and floored: a caller's delta can never push a
            // clip to a negative start, which `validate` rejects.
            clip.start = clip.start.saturating_add(delta).max(0);
        }
    }
    None
}

/// The bounds a range op works on: snapped, clamped to 0 and put in order,
/// so a drag that ended left of where it began is the same range. `None`
/// for an empty one.
fn ordered_range(project: &Project, from: Ticks, to: Ticks) -> Option<(Ticks, Ticks)> {
    let first = project.snapped(from).max(0);
    let second = project.snapped(to).max(0);
    let (start, end) = if first <= second {
        (first, second)
    } else {
        (second, first)
    };
    (end > start).then_some((start, end))
}

/// Empties `[start, end)` on every unlocked track: both bounds are cut
/// first (`split_under_playhead` IS "split every unlocked clip here"), so
/// afterwards every unlocked clip that touched the range lies entirely
/// inside it, and those are removed.
///
/// Clips on LOCKED tracks are neither split nor removed, even when they lie
/// inside the range: rule 2 is absolute, and a locked track keeps exactly
/// what it had.
///
/// The one thing this does NOT do is decide what happens to the hole, which
/// is the whole difference between a lift and a ripple delete.
fn clear_range(project: &Project, start: Ticks, end: Ticks) -> Result<Project, String> {
    // A splitter has no rule to refuse with — it either cut something or it
    // did not — so both of its non-applied answers mean "nothing was cut at
    // this bound". A splitter that ever gains a rule has to be given a way
    // out of here first: this function answers a `Project`, not an
    // [`Outcome`], so it has nowhere to put a sentence.
    let mut current = match project.split_under_playhead(start)? {
        Outcome::Applied(split) => split,
        Outcome::Identity | Outcome::Refused(_) => project.clone(),
    };
    match current.split_under_playhead(end)? {
        Outcome::Applied(split) => current = split,
        Outcome::Identity | Outcome::Refused(_) => {}
    }

    let unlocked = unlocked_tracks(&current);
    let inside: Vec<u32> = current
        .clips
        .iter()
        .filter(|c| unlocked.contains(&c.track) && c.start >= start && clip_end(c) <= end)
        .map(|c| c.id)
        .collect();
    current.clips.retain(|c| !inside.contains(&c.id));
    Ok(current)
}

// ---- the ops -------------------------------------------------------------

impl Project {
    /// Removes the named clips and closes the holes they leave: for each
    /// removed span, every clip on an UNLOCKED track that starts at or
    /// after the span's end shifts left by the span's length (spec §6).
    ///
    /// The spans are the union of the removed clips' spans and are
    /// processed RIGHT TO LEFT, because shifting for an earlier span moves
    /// the clips a later span's bounds were computed against.
    ///
    /// The named clips are removed whether or not their track is locked —
    /// the caller named them — while the lock decides only what may SHIFT.
    /// Each one's linked partner on an unlocked track goes too (AU-91).
    ///
    /// Markers do not move. A ripple can remove several spans, and a marker
    /// inside one of them has no moment left to name and nowhere to go that
    /// is not already taken by another marker; leaving every mark in place
    /// is visible and fixable, where a silent drop is not. (`insert_time`
    /// is the opposite case — one point, one length, no collision possible
    /// — and does move them.)
    ///
    /// `Err` on an unknown clip id; an identity for an empty selection.
    pub fn ripple_delete(&self, clips: &[u32]) -> Result<Outcome, String> {
        let selection = self.selected_clips(&self.with_links(clips)?)?;
        if selection.is_empty() {
            return Ok(Outcome::Identity);
        }
        let ids: Vec<u32> = selection.iter().map(|c| c.id).collect();
        let spans = union(
            selection
                .iter()
                .map(|c| Span {
                    start: c.start,
                    end: clip_end(c),
                })
                .collect(),
        );

        let mut next = self.clone();
        next.clips.retain(|c| !ids.contains(&c.id));
        for span in spans.iter().rev() {
            let length = span.end.saturating_sub(span.start);
            if let Some(why) = shift_clips(&mut next, span.end, -length) {
                return Ok(Outcome::Refused(why));
            }
        }
        // A shift can slide a clip onto a straddling neighbour on another
        // track; an overlap IS a transition, so give the newcomer the
        // default rather than leaving two stacked layers.
        let unlocked = unlocked_tracks(&next);
        self.finish_placement(next, &unlocked)
    }

    /// Removes everything between `from` and `to` on unlocked tracks and
    /// closes the hole — the range form of ripple delete (spec §6).
    ///
    /// Both bounds are cut first (`split_under_playhead` IS "split every
    /// unlocked clip here"), so afterwards every unlocked clip that touched
    /// the range lies entirely inside it; those are removed, and everything
    /// starting at or after `to` shifts left by the range's length.
    ///
    /// Clips on LOCKED tracks are neither split nor removed, even when they
    /// lie inside the range: rule 2 is absolute, and a locked track keeps
    /// exactly what it had.
    ///
    /// The bounds are snapped, clamped to 0 and ordered, so a drag that
    /// ended left of where it began is the same range. An empty range is an
    /// identity.
    ///
    /// It is [`Project::ripple_delete_ranges`] with one pair, and nothing
    /// else: with a single span there is nothing for the merge to merge and
    /// nothing for the right-to-left loop to order, so the two are
    /// step-for-step the same edit. Keeping a second body here would be a
    /// second implementation of one algorithm, free to drift.
    pub fn ripple_delete_range(&self, from: Ticks, to: Ticks) -> Result<Outcome, String> {
        self.ripple_delete_ranges(&[[from, to]])
    }

    /// Removes SEVERAL ranges and closes each hole in one edit — the
    /// silence cut (spec §6), one op because it is one undo step.
    ///
    /// **The op is defined as merge-then-cut, not as N
    /// `ripple_delete_range`s**, and the difference is visible in the
    /// document, so it is worth stating plainly: each pair is snapped,
    /// clamped to 0 and put in order exactly as the single range is, the
    /// results are MERGED — touching pairs as well as overlapping ones —
    /// and only the survivors are cut. Two quiet spans that meet leave one
    /// hole, and cutting at a boundary that no longer exists would split
    /// clips into fragments nobody asked for and burn the ids to prove it.
    /// A caller that wants N separate edits sends N ops.
    ///
    /// The survivors are cut and closed RIGHT TO LEFT, because closing an
    /// earlier hole moves the clips a later hole's bounds were measured
    /// against — every bound here is a time in the project as the caller
    /// saw it, not in the project as the previous cut left it.
    ///
    /// `set_gained_transitions` runs ONCE at the end, over the unlocked
    /// tracks, as it does for `ripple_delete`'s own union of spans: a clip
    /// that overlaps a neighbour between two shifts and then slides clear
    /// again should not come out holding a transition for an overlap that
    /// no longer exists.
    ///
    /// Everything else is `ripple_delete_range`'s contract: locked tracks
    /// are neither split, removed nor shifted; straddlers stay put; markers
    /// do not move (a marker inside a removed span has no moment left to
    /// name, and giving the plural a second marker rule would give two
    /// ripples two rules); a clip a shift brings onto a neighbour gains the
    /// default transition rather than stacking.
    ///
    /// There is no cap on the list: the op is pure, so nothing is
    /// half-applied, and a pathological call is already answered — each cut
    /// splits, every split validates, and `format::check_caps` refuses the
    /// clip count it would take to get there.
    ///
    /// An empty list, a list of empty ranges, and a list that merges to
    /// nothing all change nothing.
    pub fn ripple_delete_ranges(&self, ranges: &[[Ticks; 2]]) -> Result<Outcome, String> {
        // Snapped FIRST, merged after: two ranges three ticks apart are the
        // same range once both bounds are on the frame grid, and only a
        // merge that runs afterwards can see it.
        let spans = union(
            ranges
                .iter()
                .filter_map(|pair| ordered_range(self, pair[0], pair[1]))
                .map(|(start, end)| Span { start, end })
                .collect(),
        );
        if spans.is_empty() {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for span in spans.iter().rev() {
            next = clear_range(&next, span.start, span.end)?;
            // Negated by subtraction rather than by `-length`, so an absurd
            // range cannot overflow on the negation.
            if let Some(why) = shift_clips(&mut next, span.end, span.start.saturating_sub(span.end))
            {
                return Ok(Outcome::Refused(why));

//! Overlaps between neighbouring clips, and THE overlap rule (spec §11).
//!
//! There is no separate transition object on the timeline: an overlap
//! between two clips on the same track *is* the transition, its length is
//! the transition's duration, and the later clip's `transition_in` says
//! which one it is (spec §5.2). So this module owns three related things —
//! finding overlaps, reporting a transition's progress at a time, and the
//! rule that says which overlaps are allowed at all:
//!
//! > A clip may overlap at most ONE neighbour on each side, and each
//! > overlap must be at most HALF of the shorter of the two clips.
//!
//! The rule is written here once and called from `edit_clip` (move, trim),
//! `edit_transition` (set_transition_duration) and `edit_time` (insert time,
//! ripple): a second
//! copy would drift, and the difference between the copies would be the
//! difference between a drop the UI animates back and a project the
//! compositor cannot tile into instructions.
//!
//! Clips never push each other (spec §11): a placement that breaks the rule
//! is refused, never repaired.
//!
//! Two clips overlapping inside a NEST are a transition on exactly the same
//! terms — the group was made out of clips that already had one — so the
//! three read-only halves of this module ([`overlap_before_of`],
//! [`overlap_after_of`], [`transition_among`]) take the container's clips as
//! a slice rather than reading `Project::clips`, and the `Project` methods
//! are the timeline's spelling of them. The rule itself stays a `Project`
//! method: nothing edits inside a nest except `nest` and `unnest`, and both
//! check the TIMELINE they are moving clips on to.

use crate::actions;
use crate::audio::Side;
use crate::edit_adjustment::adjustment_overlap;
use crate::model::{Clip, Project, Transition, TransitionKind};
use crate::model_query::clips_on;
use crate::time::Ticks;

/// One overlap: `earlier` starts first, `later` is the clip whose
/// `transition_in` names the kind, and `start`/`duration` are the span in
/// PROJECT time that both clips cover.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Overlap {
    pub earlier: u32,
    pub later: u32,
    pub start: Ticks,
    pub duration: Ticks,
}

/// The maximum overlap permitted for this pair by the half-shorter rule.
pub(crate) fn overlap_limit(a: &Clip, b: &Clip) -> Ticks {
    a.duration.min(b.duration) / 2
}

/// The overlap between two clips, `earlier` being the one that starts
/// first. `None` when they merely touch: a zero-length overlap is not a
/// transition, it is a cut, and treating it as one would put a degenerate
/// division into every progress computation downstream.
fn overlap_of(earlier: &Clip, later: &Clip) -> Option<Overlap> {
    let start = earlier.start.max(later.start);
    let end = earlier
        .start
        .saturating_add(earlier.duration)
        .min(later.start.saturating_add(later.duration));
    let duration = end.saturating_sub(start);
    if duration <= 0 {
        return None;
    }
    Some(Overlap {
        earlier: earlier.id,
        later: later.id,
        start,
        duration,
    })
}

/// Where `t` sits inside the overlap, 0 at its first tick and approaching 1
/// at its last. Half-open at the end, so the tick the earlier clip ends on
/// is already past the transition and the instruction tiling has no
/// ambiguity. `None` when `t` is outside.
fn progress_in(overlap: &Overlap, t: Ticks) -> Option<f64> {
    let end = overlap.start.saturating_add(overlap.duration);
    if t < overlap.start || t >= end || overlap.duration <= 0 {
        return None;
    }
    let elapsed = t.saturating_sub(overlap.start) as f64;
    Some((elapsed / overlap.duration as f64).clamp(0.0, 1.0))
}

/// The whole transition the LATER clip of a pair carries. An overlap is
/// always a transition, so a clip that overlaps its predecessor with no
/// `transition_in` — only possible in hand-written JSON; `move_clip` sets
/// one when a clip gains an overlap — renders as the default cross
/// dissolve rather than as a hard cut through two visible layers.
///
/// The fallback is `Transition::default()` and deliberately NOT
/// `Transition::minted`: this is what a FILE means by an absent key, and a
/// version-6 project's bare overlap must go on drawing linearly and
/// silently (spec §11, R5-2). Minting is what an EDIT does.
fn transition_of_later(later: &Clip) -> Transition {
    later.transition_in.unwrap_or_default()
}

/// The overlap between `clip` and its predecessor among `clips` — one
/// container's clips, the timeline's or a nest's. `None` for an unknown
/// clip, the first clip on its track, or a plain cut.
pub(crate) fn overlap_before_of(clips: &[Clip], clip: u32) -> Option<Overlap> {
    let target = clips.iter().find(|c| c.id == clip)?;
    let ordered = clips_on(clips, target.track);
    let index = ordered.iter().position(|c| c.id == clip)?;
    let previous = ordered.get(index.checked_sub(1)?)?;
    overlap_of(previous, target)
}

/// The overlap between `clip` and its successor among `clips` — the one the
/// SUCCESSOR's `transition_in` describes.
pub(crate) fn overlap_after_of(clips: &[Clip], clip: u32) -> Option<Overlap> {
    let target = clips.iter().find(|c| c.id == clip)?;
    let ordered = clips_on(clips, target.track);
    let index = ordered.iter().position(|c| c.id == clip)?;
    let next = ordered.get(index.checked_add(1)?)?;
    overlap_of(target, next)
}

/// The transition `clip` is playing at `t`, among the clips of its own
/// container — [`Project::transition_at`]'s implementation, and the one a
/// nested clip is evaluated with (at NEST time, not project time).
///
/// The progress is EASED by the transition's own `curve` (format version 7)
/// before it is returned, so every consumer of it gets one number and none
/// of them has to know the curve exists. `actions::ease` is the crate's one
/// implementation of the four curves, and `Curve::Linear` is the identity —
/// which is what makes a version-6 file's transitions byte-identical to
/// what they were.
pub(crate) fn transition_among(
    clips: &[Clip],
    clip: u32,
    t: Ticks,
) -> Option<(TransitionKind, f64, bool, u32)> {
    let target = clips.iter().find(|c| c.id == clip)?;
    if let Some(overlap) = overlap_before_of(clips, clip) {
        if let Some(progress) = progress_in(&overlap, t) {
            // This clip is the later one, so it carries the transition.
            let transition = transition_of_later(target);
            let eased = actions::ease(transition.curve, progress);
            return Some((transition.kind, eased, true, overlap.earlier));
        }
    }
    if let Some(overlap) = overlap_after_of(clips, clip) {
        if let Some(progress) = progress_in(&overlap, t) {
            let later = clips.iter().find(|c| c.id == overlap.later)?;
            let transition = transition_of_later(later);
            let eased = actions::ease(transition.curve, progress);
            return Some((transition.kind, eased, false, overlap.later));
        }
    }
    None
}

/// The crossfade `clip` is in at `t`, among the clips of its own container:
/// `(the later clip's transition, eased progress, is_incoming)`.
///
/// The audio twin of [`transition_among`], and it differs from it in one
/// way that matters: on [`Side::Left`] the overlap is CLOSED at its end, so
/// the outgoing clip's last sample reads p = 1 and its fade finishes at
/// zero. `progress_in` is half-open — right for the picture, where the tick
/// the earlier clip ends on is already past the transition and the
/// instruction tiling must have no ambiguity — but an envelope evaluated
/// from the LEFT at that tick is asking for the limit approaching it, and
/// a `None` there would read as gain 1 and undo the whole fade on the last
/// breakpoint.
///
/// The partner id is not returned because nothing in the envelope needs it:
/// each stage multiplies its OWN term, and the two clips of a pair are
/// different voices on different composition tracks.
pub(crate) fn crossfade_among(
    clips: &[Clip],
    clip: u32,
    t: Ticks,
    side: Side,
) -> Option<(Transition, f64, bool)> {
    let closed = |overlap: &Overlap| -> Option<f64> {
        if let Some(progress) = progress_in(overlap, t) {
            return Some(progress);
        }
        if side == Side::Left && overlap.duration > 0 {
            let end = overlap.start.saturating_add(overlap.duration);
            if t == end {
                return Some(1.0);
            }
        }
        None
    };

    let target = clips.iter().find(|c| c.id == clip)?;
    if let Some(overlap) = overlap_before_of(clips, clip) {
        if let Some(progress) = closed(&overlap) {
            let transition = transition_of_later(target);
            return Some((transition, actions::ease(transition.curve, progress), true));
        }
//! Placement commit protocol: validate candidate tracks, write placements,
//! mint gained transitions, then return the edit's three-way outcome.
//!
//! It also holds what a placement is built from: `Clip::placed`, the one
//! literal of a freshly placed clip that every adding op overrides by
//! struct update; `Project::add_tracks_behind`, the tracks a placement
//! missing behind its destination inserts at the back; and [`Landing`],
//! unnest's and paste's shared landing — the wanted track, then the
//! fallbacks already added, then a new track in front.

use crate::edit_transition::set_gained_transitions;
use crate::model::{Clip, Enabled, Project, Source};
use crate::outcome::Outcome;
use crate::time::Ticks;

impl Clip {
    /// A freshly placed clip: enabled both ways, ×1, no actions, and every
    /// optional group, transition, name and label absent. Each adding op
    /// overrides what it sets by struct update.
    ///
    /// A field added to [`Clip`] later silently takes this default at every
    /// placing site. That is deliberate: a newly placed clip has none of the
    /// new state. Not a `Default` impl, because a clip with no id, track or
    /// source is not a clip.
    pub(crate) fn placed(
        id: u32,
        track: u32,
        start: Ticks,
        duration: Ticks,
        source: Source,
    ) -> Clip {
        Clip {
            id,
            track,
            start,
            duration,
            source,
            enabled: Enabled::default(),
            speed: 1.0,
            video: None,
            audio: None,
            text: None,
            shape: None,
            graphic: None,
            actions: Vec::new(),
            transition_in: None,
            name: None,
            label: None,
            linked: None,
        }
    }
}

/// Where unnest's and paste's clips land, one clip at a time, in the order
/// the caller places them: the track `depth` back from `base`, then any
/// fallback track already added, then a new track in front. Remembers the
/// tracks it touched, in first-seen order, for `finish_placement`.
pub(crate) struct Landing {
    base: i64,
    fallbacks: Vec<u32>,
    touched: Vec<u32>,
}

impl Landing {
    pub(crate) fn new(base: i64) -> Landing {
        Landing {
            base,
            fallbacks: Vec::new(),
            touched: Vec::new(),
        }
    }

    /// Lands `clip` on the first candidate the overlap rule accepts and
    /// pushes it onto `next`. A fallback track is PUSHED (in front), ordinary.
    pub(crate) fn land(&mut self, next: &mut Project, mut clip: Clip, depth: i64) {
        let wanted = next
            .tracks
            .get((self.base - depth).max(0) as usize)
            .map(|t| t.id);
        let mut chosen: Option<u32> = None;
        for candidate in wanted.into_iter().chain(self.fallbacks.iter().copied()) {
            clip.track = candidate;
            if next
                .check_overlap_rule(std::slice::from_ref(&clip), candidate, &[])
                .is_ok()
            {
                chosen = Some(candidate);
                break;
            }
        }
        // A brand-new track holds nothing, so the last arm always
        // succeeds and the loop always terminates.
        let landed = match chosen {
            Some(id) => id,
            None => {
                let track = next.numbered_track();
                let id = track.id;
                next.tracks.push(track);
                self.fallbacks.push(id);
                id
            }
        };
        clip.track = landed;
        if !self.touched.contains(&landed) {
            self.touched.push(landed);
        }
        next.clips.push(clip);
    }

    /// The tracks a clip landed on, in first-seen order.
    pub(crate) fn touched(&self) -> &[u32] {
        &self.touched
    }
}

impl Project {
    /// Inserts the tracks missing behind a placement's destination: `deepest`
    /// is the deepest depth it lands, `base` the destination's index. Each
    /// is a [`Project::numbered_track`] inserted at index 0, one at a time;
    /// inserting there shifts every existing track up, so the answer is the
    /// destination's index after them, `base` plus their count.
    pub(crate) fn add_tracks_behind(&mut self, deepest: i64, base: i64) -> i64 {
        let deficit = (deepest - base).max(0);
        for _ in 0..deficit {
            let track = self.numbered_track();
            self.tracks.insert(0, track);
        }
        base + deficit
    }

    /// Replace already resolved clips in one draft, checking old tracks
    /// before destination tracks in caller order.
    pub(crate) fn commit_replacements(&self, replacements: Vec<Clip>) -> Result<Outcome, String> {
        let mut tracks = Vec::new();
        for clip in &replacements {
            let old = self.require_clip(clip.id)?.track;
            if !tracks.contains(&old) {
                tracks.push(old);
            }
        }
        for clip in &replacements {
            if !tracks.contains(&clip.track) {
                tracks.push(clip.track);
            }
        }
        for track in &tracks {
            if let Err(why) = self.check_overlap_rule(&replacements, *track, &[]) {
                return Ok(Outcome::Refused(why));
            }
        }

        let mut next = self.clone();
        for replacement in replacements {
            if let Some(slot) = next.clip_mut(replacement.id) {
                *slot = replacement;
            }
        }
        self.finish_placement(next, &tracks)
    }

    /// Append caller-allocated clips to a private draft after checking the
    /// input project. The draft may already contain new tracks or incidental
    /// property changes, but none of the added clips.
    pub(crate) fn commit_additions(
        &self,
        mut next: Project,
        additions: Vec<Clip>,
    ) -> Result<Outcome, String> {
        let mut tracks = Vec::new();
        for clip in &additions {
            if !tracks.contains(&clip.track) {
                tracks.push(clip.track);
            }
        }
        for track in &tracks {
            if let Err(why) = self.check_overlap_rule(&additions, *track, &[]) {
                return Ok(Outcome::Refused(why));
            }
        }
        next.clips.extend(additions);
        self.finish_placement(next, &tracks)
    }

    /// Complete a placement after its caller has chosen its exact tracks.
    /// No overlap check or early identity belongs here: even a zero-distance
    /// move can gain a transition on an affected track.
    pub(crate) fn finish_placement(
        &self,
        mut next: Project,
        tracks: &[u32],
    ) -> Result<Outcome, String> {
        set_gained_transitions(&mut next, tracks);
        self.finish(next)
    }

    /// The single exit of every op: a result equal to the input is
    /// [`Outcome::Identity`] (never a copy, which would register a phantom
    /// undo step), and a result that broke an invariant is an `Err` rather
    /// than a project the rest of the crate cannot reason about.
    ///

//! Clip timing operations: trims and rate changes with source and action bounds.

use crate::edit_clip::clip_end;
use crate::edit_speed_profile::profile_factors;
use crate::model::{Clip, Project, Source};
use crate::model_words::rebase_words;
use crate::outcome::Outcome;
use crate::recipe_graphic::graphic_advanced;
use crate::source_window::source_advanced_through;
use crate::time::Ticks;

/// Speed range, `SPEED_MIN`–`SPEED_MAX` (spec §4.3, §11 #190). Three
/// readers: `set_speed` clamps to it, `rate_stretch` stays inside it, and
/// `Project::validate` refuses a clip outside it (spec §11 R6-10, amended by
/// #41). The app reads it through `rc_speed_limits` and never retypes it.
pub(crate) const SPEED_MIN: f64 = 0.1;
pub(crate) const SPEED_MAX: f64 = 1000.0;

/// The fastest a clip's audio still plays, in both pitch modes (spec §11
/// #190, the owner's decision of 2026-10-01). Above it the plan leaves the
/// clip's audio segment out (`evaluate.rs`); the video still runs to
/// `SPEED_MAX`. Chosen with a margin below a measured stall: an h264
/// export's loudness pass never finishes for a keep-pitch clip that starts
/// its audio track from ×15, nor in either mode from about ×20; ×12 and ×14
/// finish. B52a's mixer limits (×24 spectral, ×32 varispeed) hold only for
/// the mixer and an audio-only export, and are not the product's ceiling.
pub(crate) const AUDIO_SPEED_MAX: f64 = 12.0;

/// Every number about speed, as `rc_speed_limits` publishes it:
/// `{"min":0.1,"max":1000.0,"audio_max":12.0}`.
pub(crate) fn speed_limits() -> serde_json::Value {
    serde_json::json!({
        "min": SPEED_MIN,
        "max": SPEED_MAX,
        "audio_max": AUDIO_SPEED_MAX,
    })
}

impl Project {
    /// Moves the clip's start edge to `to`, advancing the source in point
    /// by `(to - start) × speed` so the frame under the edge does not move
    /// (spec §6).
    ///
    /// Clamped to the source bound — `to ≥ start - in/speed` snapped UP to
    /// a frame, `source_window.rs`'s `earliest_start_on_grid` (spec §11,
    /// D4-5) — and to leaving at least one frame of clip. Actions are
    /// deliberately left alone: clip-relative, rebasing would drop or bake
    /// whatever fell off the front, which is lossy and makes trimming back
    /// out not an identity. On a RAMPED clip the actions keep their clip
    /// time too, so `in` advances by round(S(Δ)) moving in and at the base
    /// rate moving out, and the edge is held where the clip still fits its
    /// media (`front_edge_held`, spec §11 SR-18 (c)): what plays after the
    /// new start can change. `text.words` are the opposite, on purpose
    /// (spec §11, W-3): a word is anchored to speech that stays where it is
    /// on the timeline, so every word is rebased by the trim's delta and a
    /// word trimmed off the front keeps its (negative) time. A graphic's
    /// `in` advances by the same delta (road map 10's G-9), with no speed
    /// and no head bound, never below 0.
    ///
