///
/// Either edge rolls, but they roll DIFFERENT cuts, and the op only ever
/// names the clip on the cut's right: grabbing the start edge rolls this
/// clip against its predecessor, and grabbing the end edge rolls the
/// SUCCESSOR against this one. `clip` is resolved at mouse-down, so the
/// session itself has one job.
///
/// Clamped in the preview as well as in the core, for `TrimSession`'s
/// reason: the bar must not be drawn inverted for the ticks the core is
/// busy refusing. The bounds here are the frame minimums only — the source
/// clamps need the media, which the core has and the view does not — so a
/// drag past those still looks live and lands where the core allows.
struct RollSession {
    let clip: UInt32
    /// The grabbed clip is a linked sound half: its cut rolls without the
    /// picture's (spec §11 AU-93).
    let alone: Bool
    let earliest: Ticks
    let latest: Ticks

    var time: Ticks
    var guide: Ticks?
    var didMove = false

    var op: ReelOp { .roll(clip: clip, to: time, alone: alone) }

    mutating func update(time: Ticks, snapper: TimelineSnapper) {
        let resolved = snapper.resolve(time)
        self.time = max(earliest, min(resolved.time, latest))
        guide = resolved.guide
        didMove = true
    }
}

// MARK: - Marquee

/// Rubber-band selection from empty timeline space — a lane's gap, or the

        let clip = scrollView.contentView
        let maxX = max(layout.contentWidth - clip.bounds.width, 0)
        clip.scroll(to: NSPoint(x: min(max(x, 0), maxX), y: clip.bounds.minY))
        scrollView.reflectScrolledClipView(clip)
        pinFloatingBands()
    }

    /// Auto-scroll: keeps the playhead in view while it runs (spec §4.4).
    ///
    /// Internal, not private, for `EditorViewController+NestScope.swift`:
    /// entering or leaving a nest re-roots the whole view, and `setPlayhead`
    /// above guards on `time != playhead` — which a scope change can leave
    /// equal — so that one caller has to ask for the reveal by name. The body
    /// stays here (this file is frozen at wiring), as `scroll(toX:)`'s does.
    func revealPlayhead() {
        let clip = scrollView.contentView
        let x = layout.x(for: playhead)
        let left = clip.bounds.minX + TimelineLayout.headerWidth + 24
        let right = clip.bounds.maxX - 24
        guard x < left || x > right else { return }
        scroll(toX: x - TimelineLayout.headerWidth - clip.bounds.width * 0.35)
    }

    // MARK: - Refusal

    /// A drop the core refused springs back instead of just beeping
    /// (spec §4.4). The ghost is drawn by `TimelineContentView`; this only
    /// runs the clock.
    func flashRefusal(from: CGRect, to: CGRect) {
        refusalTimer?.invalidate()
        refusal = (from: from, to: to, progress: 0)
        let started = Date()
        refusalTimer = Timer.scheduledTimer(withTimeInterval: 1.0 / 60, repeats: true) {
            [weak self] timer in
            guard let self = self else {
                timer.invalidate()
                return
            }
            let progress = CGFloat(Date().timeIntervalSince(started) / 0.22)
            if progress >= 1 {
                timer.invalidate()
                self.refusalTimer = nil
                self.refusal = nil
            } else {
                self.refusal?.progress = progress
            }
            self.content.needsDisplay = true
        }
    }

    // MARK: - Inline rename

    /// One editor for both renames (a track header, a marker). It is a real
    /// subview of the floating band it edits, which is why those bands let
    /// their subviews be hit even though they refuse hits themselves.
    func beginRename(
        in host: NSView, frame: NSRect, text: String, relocate: (() -> NSRect?)? = nil,
        commit: @escaping (String) -> Void
    ) {
        // Whatever else is being typed into commits FIRST, refresh and all:
        // a commit's refresh rebuilds the layout, and a field added before it
        // ran would be relocated (or ended) under the first-responder handoff.
        _ = window?.makeFirstResponder(nil)
        endRename()
        let field = NSTextField(string: text)
        field.frame = frame
        field.font = DS.sans(11)
        field.isBordered = true
        field.isBezeled = true
        field.drawsBackground = true
        field.focusRingType = .none
        field.delegate = self
        // While a field is open, the band that HOLDS it is the front-most
        // band — or a track's field, which sits at its ROW's top, disappears
        // under the ruler on the top, partly scrolled row (`init` above and
        // `TimelineView+NestScope.swift` for why the ruler is up there; that
        // file argues why this is unconditional and what it costs).
        // `endRename` gives the corner back.
        //
        // Before the field is added, never after:
        // `addSubview(_:positioned:relativeTo:)` MOVES a view that is already
        // a subview, which would take the field editor out of the hierarchy
        // and end the editing it had just been given.
        if host !== content { content.addSubview(host, positioned: .above, relativeTo: nil) }
        host.addSubview(field)
        renameField = field
        renameRelocate = relocate
        let original = text.trimmingCharacters(in: .whitespacesAndNewlines)
        renameCommit = { value in
            // Unchanged is not a rename: on a clip it would pin the fallback
            // as an own name; on a track or a marker it is the core's identity.
                onEdit?("Reorder Track", [op])
            }
        } else if actionDrag != nil {
            endActionDrag()
        }
        content.needsDisplay = true
        headers.needsDisplay = true
    }

    /// Compares what the drag asked for with what the core did. `onLiveEnd`
    /// has already published, so `snapshot` is the answer.
    private func checkRefusal(of session: ClipDragSession) {
        // A drop that asked for a new track lands on a row that did not exist
        // when the drag started, so there is nothing to compare — and a drop
        // that duplicated moved the copies, not the anchor.
        guard session.didMove, !session.duplicating, !session.needsNewTrack,
              let clip = snapshot.clip(session.anchor),
              let index = snapshot.trackIndex(of: clip.track)
        else { return }
        let landedRow = layout.row(forTrackIndex: index)
        guard clip.start != session.proposedStart || landedRow != session.row else { return }
        let row = min(max(session.row, 0), max(layout.trackCount - 1, 0))
        // Both ends of the springback are the clip's BODY, not its lane rect:
        // the redesign insets a bar 3 pt top and bottom
        // (`TimelineContentView.bodyRect`), so a ghost built from the lane
        // would be a taller rectangle than the clip it claims to be — and it
        // is drawn on the clip's own corner radius, over the clip, where the
        // difference is the whole point of the animation.
        var ghost = TimelineContentView.bodyRect(layout.clipRect(clip, row: row))
        ghost.origin.x = layout.x(for: session.proposedStart)
        flashRefusal(
            from: ghost,
            to: TimelineContentView.bodyRect(layout.clipRect(clip, row: landedRow)))
    }

    private func beginClipDrag(anchor: UInt32, at point: CGPoint, flags: NSEvent.ModifierFlags) {
        guard let clip = snapshot.clip(anchor),
              let index = snapshot.trackIndex(of: clip.track),
              !snapshot.tracks[index].locked
        else { return }
        let ids = selection.contains(anchor) ? Array(selection) : [anchor]
        let dragged = snapshot.clips.filter { ids.contains($0.id) }
        guard !dragged.isEmpty else { return }
        let duplicating = flags.contains(.option)

        // Every id the ops will need, probed against the handle the gesture
        // is about to snapshot — the ONE moment the current project and the
        // live-edit base are the same thing.
        let existingClips = Set(snapshot.clips.map { $0.id })
        let existingTracks = Set(snapshot.tracks.map { $0.id })
        var copies: [UInt32] = []
        var copyShift: Ticks = 0
        var prefix: [ReelOp] = []
        if duplicating {
            let probed = onProbe?([.duplicate(clips: ids)])
            let made = (probed?.clips ?? []).filter { !existingClips.contains($0.id) }
                .sorted { $0.start < $1.start }
            if !made.isEmpty {
                copies = made.map { $0.id }
                let from = dragged.map { $0.start }.min() ?? 0
                copyShift = (made.map { $0.start }.min() ?? from) - from
                prefix = [.duplicate(clips: ids)]
            }
        }
        let count = snapshot.tracks.count
        let top = probeTrack(prefix + [.addTrack(index: count)], existing: existingTracks)
        let bottom = probeTrack(prefix + [.addTrack(index: 0)], existing: existingTracks)

        dragBase = snapshot
        dragHeights = TimelineLayout.trackHeights(
            for: snapshot, sizeIndex: trackHeightIndex)
        dragRowHeights = layout.rowHeights
        dragSnapper = makeSnapper(excluding: ids, suppressed: flags.contains(.command))
        clipDrag = ClipDragSession(
            clips: ids, anchor: anchor, anchorStart: clip.start,
            anchorRow: layout.row(forTrackIndex: index),
            grabTime: layout.time(atX: point.x),
            spanStart: dragged.map { $0.start }.min() ?? clip.start,
            trackCount: count, duplicating: !copies.isEmpty, copies: copies, copyShift: copyShift,
            newTrackTop: top, newTrackBottom: bottom,
            row: layout.row(forTrackIndex: index))
        onLiveBegin?()
    }

    private func probeTrack(_ ops: [ReelOp], existing: Set<UInt32>) -> UInt32? {
        guard let probed = onProbe?(ops) else { return nil }
        return probed.tracks.first { !existing.contains($0.id) }?.id
    }

    private func beginTrim(_ id: UInt32, edge: TimelineEdge, flags: NSEvent.ModifierFlags) {
        guard let clip = snapshot.clip(id),
              let index = snapshot.trackIndex(of: clip.track),
              !snapshot.tracks[index].locked
        else { return }
        let frame = max(snapshot.canvas.fps.frameDuration, 1)
        dragSnapper = makeSnapper(excluding: [id], suppressed: flags.contains(.command))
        trim = TrimSession(
            clip: id, edge: edge,
            stretch: flags.contains(.option) && clip.source.hasSourceBound,
            alone: clip.isLinkedSound,
            originalStart: clip.start, originalEnd: clip.end, frame: frame,
            time: edge == .start ? clip.start : clip.end)
        onLiveBegin?()
    }

    /// The destination track id for the row a drag is over, or nil to leave
    /// every clip on its own track. Read from the gesture's base handle.
    private func destination(for session: ClipDragSession) -> UInt32? {
        guard let base = dragBase, session.row != session.anchorRow,
              (0..<base.tracks.count).contains(session.row)
        else { return nil }
        return base.tracks[base.tracks.count - 1 - session.row].id
    }

    /// ⌥-click a track header: every clip on it (spec §9). Here rather than
    /// in `EditorViewController+Edge.swift` only because `selection` is
    /// `private(set)` — it is the same view-state channel `selectClip` and
    /// the marquee use, and registers no undo step.
    private func selectClipsOnTrack(_ track: UInt32) {
        let ids = Set(snapshot.clips.filter { $0.track == track }.map { $0.id })
        guard selection != ids else { return }
        selection = ids
        onSelectionChanged?(selection)
    }

    /// A press on empty timeline space — a lane's gap, or above or below
    /// the lanes: a bare press clears the selection and ⇧ keeps it, then the
    /// band starts (`RangeSession`). One body for `.lane` and `.outside`, so
    /// the two places a band can start cannot drift apart. The clear is
    /// posted at the press rather than at the first drag, which is what
    /// makes a bare CLICK on empty space deselect.
    private func beginMarquee(at point: CGPoint, flags: NSEvent.ModifierFlags) {
        if !flags.contains(.shift), !selection.isEmpty {
            selection = []
            onSelectionChanged?(selection)
        }
        marquee = RangeSession(
            origin: point, additive: flags.contains(.shift), base: selection, current: point)
    }

    private func selectClip(_ id: UInt32, flags: NSEvent.ModifierFlags) {
        if flags.contains(.shift) {
            if selection.contains(id) {
                selection.remove(id)
            } else {
                selection.insert(id)
            }
        } else if !selection.contains(id) {
            selection = [id]
        }
        onSelectionChanged?(selection)
    }

    private func toggleHeader(_ button: TimelineHeaderButton, row: Int) {
        guard let track = track(atRow: row) else { return }
        toggle(button, on: track)
    }

    private func renameTrack(_ track: TrackSnapshot, row: Int) {
        beginRename(
            in: headers, frame: trackRenameFrame(row: row), text: track.name,
            relocate: trackRenameRelocator(track.id)
        ) { [weak self] name in
            self?.onGroupedEdit?("Rename Track", [.setTrack(track: track.id, name: name)])
        }
    }

    private func renameMarker(_ marker: MarkerSnapshot) {
        beginRename(
            in: ruler, frame: markerRenameFrame(marker), text: marker.name,
            relocate: markerRenameRelocator(marker.id)
        ) { [weak self] name in
            self?.onGroupedEdit?("Rename Marker", [.setMarker(marker: marker.id, name: name)])
        }
    }

    // MARK: - Shared lookups (the drawing views use these too)

    func track(atRow row: Int) -> TrackSnapshot? {
        let index = layout.trackIndex(forRow: row)
        return snapshot.tracks.indices.contains(index) ? snapshot.tracks[index] : nil
    }

    /// True when the clip contributes samples, i.e. deserves a waveform and
    /// fade handles. A nest clip has no media but does have a mix — the core
    /// gives it audio props exactly when something inside it sings, and its
    /// fades apply to all of that (`core/src/audio.rs`) — so it gets the
    /// handles. There is no waveform to draw for one; `drawWaveform` finds no
    /// media and returns.
    func hasAudio(_ clip: ClipSnapshot) -> Bool {
        guard clip.enabled.audio else { return false }
        if case .nest = clip.source { return clip.audio != nil }
        guard let media = snapshot.media(for: clip) else { return false }
        return media.hasAudio
    }

    /// True when the clip contributes pixels — a filmstrip goes here.
    func hasVideo(_ clip: ClipSnapshot) -> Bool {
        guard clip.enabled.video else { return false }
        switch clip.source {
        case .media, .still, .image: return snapshot.media(for: clip)?.hasVideo ?? false
        case .text, .shape, .graphic, .nest, .adjustment: return false
        }
    }

    /// Source time under a timeline time, for the filmstrip and the waveform.
    /// Source advances at `speed` per timeline tick (spec §6 `set_speed`).
    ///
    /// **Mirrored when the clip plays backwards** (`ReverseMirror`, spec §11
    /// D4-6): the caches both callers index are the FORWARD file's, while `in`
    /// and this offset are measured in the stream the clip PLAYS. It is inside
    /// this function so the filmstrip and the waveform cannot diverge; the
    /// compositor needs no mirror because it swaps the asset instead.
    static func sourceTime(of clip: ClipSnapshot, in media: MediaSnapshot, at t: Ticks) -> Ticks {
        let rate = clip.speed > 0 ? clip.speed : 1
        let offset = Double(t - clip.start) * rate
        let source = clip.source.sourceIn + TimelineLayout.ticks(clamping: offset)
        guard clip.source.isReversed else { return source }
        return ReverseMirror.mirrored(source, about: media.duration)
    }
}

// MARK: - Caches

/// Thumbnails and waveform peaks, kept out of `draw(_:)`'s way.
///
/// `MediaImporter` writes both to the document's cache directory; reading a
/// peaks file is a whole-file read and a filmstrip is one file per tile, so a
/// redraw that went to disk every time would make scrolling crawl. Misses are
/// remembered too — a project whose caches have not been generated yet must
/// not re-stat the same missing file sixty times a second.
final class TimelineCaches {
    private var thumbnailCache: [String: CGImage] = [:]
    private var thumbnailMisses: Set<String> = []
    private var peakCache: [UInt32: [Float]] = [:]
    private var peakMisses: Set<UInt32> = []

    /// Well past a screenful of tiles; the whole table is dropped rather than
    /// evicted one by one, because the next scroll refills what it needs.
    private static let thumbnailLimit = 800

    /// `index` is a whole second of SOURCE time, which is how
    /// `MediaImporter` names the files.
    func thumbnail(media: UInt32, index: Int, in directory: URL) -> CGImage? {
        let key = "\(media)/\(index)"
        if let image = thumbnailCache[key] { return image }
        if thumbnailMisses.contains(key) { return nil }
        guard let image = MediaImporter.loadThumbnail(for: media, index: index, in: directory)
        else {
            thumbnailMisses.insert(key)
            return nil
        }
        if thumbnailCache.count >= Self.thumbnailLimit {
            thumbnailCache.removeAll(keepingCapacity: true)
        }
        thumbnailCache[key] = image
        return image
    }

    /// 100 buckets per second of source, mono, max magnitude.
    func peaks(media: UInt32, in directory: URL) -> [Float]? {
        if let cached = peakCache[media] { return cached }
        if peakMisses.contains(media) { return nil }
        guard let loaded = MediaImporter.loadPeaks(for: media, in: directory) else {
            peakMisses.insert(media)
            return nil
        }
        peakCache[media] = loaded
        return loaded
    }

    /// Called for every `.mediaCacheDidChange`. Thumbnails post repeatedly as
    /// they land, so only the misses need clearing there — a tile already
    /// read is still the same tile. That is true while a strip is being
    /// filled in and false once it has been REPLACED (a relink, a changed
    /// file), which is what `replaced` says: then the hits go too, or the old
    /// film's tiles stay on screen until the 800-entry drop.
    func invalidate(media: UInt32, kind: String?, replaced: Bool = false) {
        if kind == MediaImporter.peaksKind || kind == nil {
            peakCache.removeValue(forKey: media)
            peakMisses.remove(media)
        }
        if kind == MediaImporter.thumbsKind || kind == nil {
            let prefix = "\(media)/"
            thumbnailMisses = thumbnailMisses.filter { !$0.hasPrefix(prefix) }
            if replaced { thumbnailCache = thumbnailCache.filter { !$0.key.hasPrefix(prefix) } }
        }
    }

    func purge() {
        thumbnailCache.removeAll()

                return Ok(Outcome::Refused(why));
            }
        }
        let unlocked = unlocked_tracks(&next);
        self.finish_placement(next, &unlocked)
    }

    /// Removes everything between `from` and `to` on unlocked tracks and
    /// leaves the hole open — `ripple_delete_range` without the close
    /// (spec §6).
    ///
    /// The lift is the cut that costs nothing downstream: every clip that
    /// starts at or after `to` keeps the moment it had, so a mix, a caption
    /// track and a music bed stay where they were cut to. It is the
    /// counterpart of a ripple, not a lesser one — ⌫ with a range and
    /// nothing selected, where ⌘⌫ ripples.
    ///
    /// Markers do not move either, for the plainer reason that nothing
    /// under them did.
    ///
    /// The bounds are snapped, clamped to 0 and ordered, so a drag that
    /// ended left of where it began is the same range. An empty range, or
    /// one that held nothing an unlocked track could give up, is an identity.
    pub fn lift_range(&self, from: Ticks, to: Ticks) -> Result<Outcome, String> {
        let Some((start, end)) = ordered_range(self, from, to) else {
            return Ok(Outcome::Identity);
        };
        // No shift, so nothing can be brought into contact with anything
        // and no transition can be gained.
        self.finish(clear_range(self, start, end)?)
    }

    /// Closes the empty span on `track` that contains `at`: everything from
    /// the far side of it, on every unlocked track, moves left by the gap's
    /// length (spec §6).
    ///
    /// The gap is bounded by the nearest clip edges ON `track` — the last
    /// end at or before `at`, or 0 when nothing precedes it, and the first
    /// start after it. A playhead ON a clip is not in a gap, and a gap with
    /// nothing after it is not one to close: both refuse, naming the clip or
    /// the track (spec §11 #88).
    ///
    /// The shift is the ripple's, timeline-wide over unlocked tracks with
    /// straddlers staying put, so the material that follows the gap keeps
    /// its relative timing on every track. **A locked `track` refuses in
    /// [`locked_track`]'s words**: its own clips are the ones that would not
    /// move, and closing a gap by shifting everything except the track the
    /// gap is on is not what anyone asked for.
    ///
    /// **Refuses when the shift would break the overlap rule** anywhere it
    /// moved something, rather than closing as far as it can. A gap closes
    /// fully or not at all: a partial close leaves the user looking at a
    /// smaller gap with no way to tell whether the op ran.
    ///
    /// Markers do not move, as they do not for any other ripple (only
    /// `insert_time`, where no collision is possible, moves them).
    ///
    /// `Err` for an unknown track.
    pub fn close_gap(&self, track: u32, at: Ticks) -> Result<Outcome, String> {
        if self.require_track(track)?.locked {
            return Ok(Outcome::Refused(locked_track(
                track,
                "the gap on it cannot be closed",
            )));
        }
        let at = self.snapped(at).max(0);
        let ordered = self.clips_on_track(track);
        if let Some(on) = ordered.iter().find(|c| c.start <= at && at < clip_end(c)) {
            return Ok(Outcome::Refused(format!(
                "clip {} runs from {} to {} on track {track}, so {at} is not in a gap",
                on.id,
                on.start,
                clip_end(on)
            )));
        }
        let start = ordered
            .iter()
            .map(|c| clip_end(c))
            .filter(|end| *end <= at)
            .max()
            .unwrap_or(0);
        let Some(end) = ordered.iter().map(|c| c.start).filter(|s| *s > at).min() else {
            return Ok(Outcome::Refused(format!(
                "no clip on track {track} starts after {at}, so there is no gap to close"
            )));
        };
        if end <= start {
            return Ok(Outcome::Identity);
        }

        // Only the tracks something actually moves on can gain an overlap,
        // and only those are checked: a rule violation elsewhere is not
        // this op's to report, and refusing over one would make a gap
        // uncloseable for a reason the user cannot see.
        let mut touched: Vec<u32> = Vec::new();
        for clip in shifted(self, end).iter().filter_map(|id| self.clip(*id)) {
            if !touched.contains(&clip.track) {
                touched.push(clip.track);
            }
        }

        let mut next = self.clone();
        if let Some(why) = shift_clips(&mut next, end, start.saturating_sub(end)) {
            return Ok(Outcome::Refused(why));
        }
        for id in &touched {
            if let Err(why) = next.check_overlap_rule(&[], *id, &[]) {
                return Ok(Outcome::Refused(why));
            }
        }
        self.finish_placement(next, &touched)
    }

    /// Opens `length` of empty time at `at`: every clip on an unlocked
    /// track that starts at or after `at` shifts right, and straddling
    /// clips stay put (spec §6).
    ///
    /// Markers at or after `at` shift too. A marker names a moment in the
    /// CUT — "the intro ends here" — not a wall-clock time, so material
    /// inserted before it must carry it along; a marker left behind would
    /// point at whatever the insert pushed under it. No marker can collide:
    /// every mark at or after `at` moves by the same length, and the ones
    /// before it never reach `at`.
    ///
    /// `Err` for a length still negative after snapping; an identity for zero.
    pub fn insert_time(&self, at: Ticks, length: Ticks) -> Result<Outcome, String> {
        let at = self.snapped(at).max(0);
        let length = self.snapped(length);
        if length < 0 {
            return Err(format!("insert length must not be negative, not {length}"));
        }
        if length == 0 {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        // A positive shift has no floor to refuse.
        let _ = shift_clips(&mut next, at, length);
        for marker in next.markers.iter_mut() {
            if marker.time >= at {
                marker.time = marker.time.saturating_add(length);
            }
        }
        self.finish(next)
    }

    /// Holds the frame under `at` for `duration` (default two seconds),
    /// spec §6.
    ///
    /// The three-op composition IS the definition: **split** the clip at
    /// `at`, **insert time** so `duration` of empty timeline opens across
    /// every unlocked track — which is what keeps the rest of the cut in
    /// sync with the hold (spec §11) — and then fill the hole this clip's
    /// track now has with a `still` naming the source time that was under
    /// the playhead. No image is extracted: a still is one source frame
    /// scaled in the composition (spec §11).
    ///
    /// The source time is `in + (at - start) × speed`, clamped inside the
    /// media so the still names a frame that exists. The still carries the
    /// clip's video properties EVALUATED at the cut, not its base ones: the
    /// frozen frame must sit exactly where the frame it froze sat, and an
    /// action may have been moving it. For the same reason the still gets
    /// no actions — the state it froze at is baked into its base props, and
    /// a copied action would animate away from the frame the cut matched.
    ///
    /// `Err` for an unknown clip, a non-media source, an `at` outside the
    /// clip, or a duration under one frame; refused, in the rule's own
    /// sentence, if the still would break the overlap rule.
    pub fn freeze_frame(
        &self,
        clip: u32,
        at: Ticks,
        duration: Option<Ticks>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let Source::Media { media, r#in, .. } = target.source else {
            return Err(format!("clip {clip} is not a media clip"));
        };
        // A clip with no video props draws nothing, so there is no frame to
        // hold — the same "presence of the group is the aspect" rule the
        // property patches use.
        if target.video.is_none() {
            return Err(format!("clip {clip} has no video properties"));
        }

        let at = self.snapped(at);
        if at < target.start || at > clip_end(&target) {
            return Err(format!("clip {clip} does not cover {at}"));
        }
