for name, edits in EDITS.items():
    path = ROOT / name
    text = path.read_text()
    for old, new in edits:
        if text.count(old) != 1:
            raise SystemExit(f"{name}: {text.count(old)} matches for: {old[:60]}")
        text = text.replace(old, new)
    path.write_text(text)
    print(name, len(edits))
